import{_ as t,o,c as r,a2 as a}from"./chunks/framework.M7K9TQZf.js";const u=JSON.parse('{"title":"Browser support","description":"The oldest browsers each package works in, the platform features that decide those versions, and what someone on an older browser loses.","frontmatter":{"title":"Browser support"},"headers":[],"relativePath":"browser-support.md","filePath":"en/browser-support.md","lastUpdated":1789266244000}'),s={name:"browser-support.md"};function d(i,e,n,h,l,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="browser-support" tabindex="-1">Browser support <a class="header-anchor" href="#browser-support" aria-label="Permalink to &quot;Browser support&quot;">​</a></h1><p class="plass-lede">The oldest browsers each package works in, the platform features that decide those versions, and what someone on an older browser loses.</p><div class="plass-fw" data-fw="react"><h2 id="minimum-versions" tabindex="-1">Minimum versions <a class="header-anchor" href="#minimum-versions" aria-label="Permalink to &quot;Minimum versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Browser</th><th>Full support</th><th>Works, with gaps</th><th>Not supported</th></tr></thead><tbody><tr><td>Chrome, Edge</td><td>111</td><td>None</td><td>110 and older</td></tr><tr><td>Firefox</td><td>128</td><td>113 to 127</td><td>112 and older</td></tr><tr><td>Safari, Safari on iOS</td><td>16.4</td><td>None</td><td>16.3 and older</td></tr></tbody></table><p><strong>Full support</strong> means every component looks and behaves as its page describes. <strong>Works, with gaps</strong> means the components run and stay usable, without the features listed under <a href="#what-older-browsers-lose">What older browsers lose</a>.</p><p>Chrome 111 and Safari 16.4 were released in March 2023, and Firefox 128 in July 2024. Any other browser built on Chromium follows its Chromium version. Chrome and Firefox on iOS run on Safari&#39;s engine, so the Safari row applies to them.</p><p>Both stylesheets draw the same line. <code>plass-ui/styles.css</code> is compiled for these versions, and a project that imports <code>plass-ui/tailwind.css</code> compiles it with its own Tailwind CSS v4, which <a href="https://tailwindcss.com/docs/compatibility" target="_blank" rel="noreferrer">targets the same three browsers</a>.</p><h2 id="what-decides-it" tabindex="-1">What decides it <a class="header-anchor" href="#what-decides-it" aria-label="Permalink to &quot;What decides it&quot;">​</a></h2><p>CSS decides the line, not JavaScript. A bundler can rewrite newer syntax and a polyfill can add a missing function, but nothing added to a build gives a browser a CSS feature it does not have.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Chrome</th><th>Firefox</th><th>Safari</th><th>Used for</th></tr></thead><tbody><tr><td><code>color-mix()</code></td><td>111</td><td>113</td><td>16.2</td><td>Every colour family&#39;s focus ring, soft fill, edge and tinted shadow</td></tr><tr><td>Base UI</td><td>111</td><td>113</td><td>16.4</td><td>The behaviour and accessibility of the interactive components</td></tr><tr><td>Tailwind CSS v4</td><td>111</td><td>128</td><td>16.4</td><td>The compiled utilities and the theme values they read</td></tr></tbody></table><p><strong><code>color-mix()</code> is the hard line.</strong> In a browser without it, every property that reads one of those tokens falls back to its default. The focus ring disappears together with the hover fills, the coloured edges and the tinted shadows, and someone using a keyboard can no longer see where the focus is.</p><p><a href="https://base-ui.com/react/overview/about" target="_blank" rel="noreferrer">Base UI</a> supports the browsers that were Baseline Widely Available when its current major version was released. Safari 16.2 and 16.3 have every CSS feature the hard line needs, but they are outside that range, so Safari has no versions that work with gaps.</p><p>Tailwind CSS v4 targets Firefox 128, and its compiled utilities carry fallbacks for older Firefox releases. What Firefox 113 to 127 still miss is listed in the next section.</p><p>The JavaScript is well below the line. The JavaScript in <code>dist/</code>, in Base UI and in React uses no syntax newer than Chrome 91, Firefox 79 and Safari 14.1.</p><h2 id="what-older-browsers-lose" tabindex="-1">What older browsers lose <a class="header-anchor" href="#what-older-browsers-lose" aria-label="Permalink to &quot;What older browsers lose&quot;">​</a></h2><p>Firefox 113 to 127 run the components without these features:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Firefox</th><th>Without it</th></tr></thead><tbody><tr><td><code>:has()</code></td><td>121</td><td><code>PlTextField</code>, <code>PlSelect</code>, <code>PlCombobox</code>, <code>PlNumberField</code>, <code>PlRating</code> and the picker fields (<code>PlDatePicker</code>, <code>PlDateRangePicker</code>, <code>PlDateTimePicker</code>, <code>PlTimePicker</code>, <code>PlColorPicker</code>, <code>PlTreeSelect</code>) draw no focus ring. They still take focus; only the ring is missing.</td></tr><tr><td><code>lh</code> unit</td><td>120</td><td>A checkbox tick, a radio dot, an alert&#39;s glyph and the other icons placed beside a label can sit slightly above the middle of the label&#39;s first line.</td></tr><tr><td><code>Intl.Segmenter</code></td><td>125</td><td><a href="./components/transitions/animate-typing"><code>PlAnimateTyping</code></a> advances one code point at a time, so an emoji built from several code points appears in pieces.</td></tr><tr><td><code>@property</code></td><td>128</td><td>The light in <a href="./components/transitions/animate-lighting"><code>PlAnimateLighting</code></a> stays in place instead of travelling around the edge.</td></tr></tbody></table><p>The first row affects keyboard users most, because the fields that lose their ring are the ones they fill in. If an application has to work well with a keyboard, treat Firefox 121 as its minimum.</p><h2 id="newer-features-used-where-they-exist" tabindex="-1">Newer features used where they exist <a class="header-anchor" href="#newer-features-used-where-they-exist" aria-label="Permalink to &quot;Newer features used where they exist&quot;">​</a></h2><p>Some features are missing from browsers inside the full-support range. Each one is used only where the browser has it, and a browser without it gets the result in the last column.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Chrome</th><th>Firefox</th><th>Safari</th><th>Used for</th><th>Without it</th></tr></thead><tbody><tr><td><code>animation-timeline</code></td><td>115</td><td>Not yet</td><td>26</td><td><code>timeline=&quot;view&quot;</code> on the transition effects, which follows the scroll position</td><td>The effect runs on its <code>duration</code>, as it does without <code>timeline</code></td></tr><tr><td><code>fetchpriority</code></td><td>101</td><td>132</td><td>17.2</td><td><code>priority</code> on <a href="./components/display/image"><code>PlImage</code></a>, which asks for the picture a page is judged by ahead of the others</td><td>The picture is still fetched eagerly, at the browser&#39;s default priority</td></tr><tr><td><code>hidden=&quot;until-found&quot;</code></td><td>102</td><td>139</td><td>26.2</td><td><code>hiddenUntilFound</code> on <a href="./components/surfaces/accordion"><code>PlAccordion</code></a> and <a href="./components/surfaces/collapsible"><code>PlCollapsible</code></a>, which lets find-in-page open a closed panel</td><td>Text inside a closed panel is not found</td></tr><tr><td><code>Intl.Locale</code> week data</td><td>99</td><td>153</td><td>15.4</td><td>Calendars start the week on the day the locale starts it</td><td>The week starts on Sunday unless <code>weekStartsOn</code> is set on the component or on <a href="./guide/defaults"><code>PlassProvider</code></a></td></tr></tbody></table><p>Firefox before 148 and Safari open the panel that holds the match, but do not scroll to the matched text correctly.</p><h2 id="how-these-versions-were-found" tabindex="-1">How these versions were found <a class="header-anchor" href="#how-these-versions-were-found" aria-label="Permalink to &quot;How these versions were found&quot;">​</a></h2><p>Every pull request runs the React test suite in the Chromium, Firefox and WebKit builds that Playwright ships, on Linux, Windows and macOS. Those builds follow the current releases, so older versions are not tested.</p><p>The versions on this page come from what the package ships, checked against <a href="https://github.com/mdn/browser-compat-data" target="_blank" rel="noreferrer">MDN&#39;s browser compatibility data</a>: the compiled stylesheet, the JavaScript in <code>dist/</code>, and the Base UI release the package depends on. The Base UI and Tailwind CSS rows are what those projects state for themselves. The page was last checked against <code>plass-ui</code> 1.4.0 and <code>@base-ui/react</code> 1.8.0.</p></div><div class="plass-fw" data-fw="flutter"><h2 id="flutter-web" tabindex="-1">Flutter web <a class="header-anchor" href="#flutter-web" aria-label="Permalink to &quot;Flutter web&quot;">​</a></h2><p><code>plass_ui</code> adds no browser requirement of its own. The Flutter engine draws every component, and the package has no web-specific code, so a Flutter web app that uses it runs in the same browsers as one that does not. Those browsers are set by the Flutter SDK the app is built with, which is 3.41 or later.</p><p>At the time of writing, <a href="https://docs.flutter.dev/reference/supported-platforms" target="_blank" rel="noreferrer">Flutter&#39;s supported platforms page</a> lists these for Flutter 3.47:</p><table tabindex="0"><thead><tr><th>Browser</th><th>Supported</th><th>Not supported</th></tr></thead><tbody><tr><td>Chrome, Edge</td><td>The latest two versions</td><td>95 and older</td></tr><tr><td>Firefox</td><td>The latest two versions</td><td>98 and older</td></tr><tr><td>Safari</td><td>15.6 and newer</td><td>15.5 and older</td></tr></tbody></table><p>Flutter does not say whether the versions between the two columns work.</p><p><code>flutter build web</code> compiles to JavaScript. A build with <code>--wasm</code> adds a WebAssembly version and keeps the JavaScript one, which Flutter uses in browsers that cannot run the WebAssembly version. <a href="https://docs.flutter.dev/platform-integration/web/wasm" target="_blank" rel="noreferrer">Flutter&#39;s WebAssembly page</a> lists which browsers currently run it.</p><h2 id="other-platforms" tabindex="-1">Other platforms <a class="header-anchor" href="#other-platforms" aria-label="Permalink to &quot;Other platforms&quot;">​</a></h2><p>The same holds on Android, iOS, Linux, macOS and Windows: the package runs wherever Flutter 3.41 or later does, and the supported platforms page lists the versions.</p></div>',4)])])}const f=t(s,[["render",d]]);export{u as __pageData,f as default};
